'use strict';

// MODULES //

var factory = require( './factory.js' );
var randuint32 = require( './rand_uint32.js' );


// MAIN //

/**
* Generates a pseudorandom integer on the interval \\( [0, 2^{32}) \\).
*
* ## Method
*
* -   TinyMT32 uses a state of only 127 bits, consisting of four 32-bit integers, making it more memory efficient than MT19937.
*
* -   The state transition involves the following steps:
*     ```javascript
*     y = state[3];
*     x = (state[0] & 0x7FFFFFFF) ^ state[1] ^ state[2];
*     x ^= (x << 1);
*     y ^= (y >> 1) ^ x;
*     state[0] = state[1];
*     state[1] = state[2];
*     state[2] = x ^ (y << 10);
*     state[3] = y;
*     ```
*
* -   The tempering function uses two magic constants (MAT1 = 0x8F7011EE, MAT2 = 0xFC78FF1F) when y is odd:
*     ```javascript
*     if (y & 1) {
*         state[1] ^= MAT1;
*         state[2] ^= MAT2;
*     }
*     ```
*
* -   The final output is generated using another magic constant (TMAT = 0x3793FDFF):
*     ```javascript
*     y = state[0] + (state[2] >> 8);
*     return (y ^ TMAT) >>> 0;
*     ```
*
* -   For normalized double-precision floating-point numbers, we multiply the generated 32-bit integer by \\( 2^{-53} \\), which ensures a uniform distribution on [0,1).
*
* ## References
*
* -   Saito, Mutsuo, and Matsumoto, Makoto. 2011. "Tiny Mersenne Twister (TinyMT): A small-sized variant of Mersenne Twister."
*     <http://www.math.sci.hiroshima-u.ac.jp/~m-mat/MT/TINYMT/index.html>
*
* @function tinymt32
* @type {PRNG}
* @returns {PositiveInteger} pseudorandom integer
*
* @example
* var v = tinymt32();
* // returns <number>
*/
var tinymt32 = factory({
	'seed': randuint32()
});


// EXPORTS //

module.exports = tinymt32;
